// Writes include/tables.h from the browser preview's tables (backend/score67/static/led.mjs),
// so the panel draws exactly what the preview shows. Run: node tools/gen_tables.mjs
import {SMALL, CLOCK, NARROW, ICONS, ICON_COLORS, COLORS, WIDTH, HEIGHT} from '../../backend/score67/static/led.mjs';
import {writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';

const rgb = hex => parseInt(hex.slice(1), 16);
const lines = [
  '// Generated by tools/gen_tables.mjs from backend/score67/static/led.mjs - do not edit.',
  '#pragma once', '#include <stdint.h>', '',
  `constexpr int LED_W = ${WIDTH}, LED_H = ${HEIGHT};`, '',
  '// 3x5 glyphs: ASCII 32..90, five rows of three bits (MSB = left); unknown = space.',
  'const uint8_t FONT_SMALL[59][5] = {',
];
for (let c = 32; c <= 90; c++) {
  const g = SMALL[String.fromCharCode(c)] || SMALL[' '];
  lines.push(`  {${g.join(', ')}},  // '${String.fromCharCode(c)}'`);
}
lines.push('};', '', '// 5x7 digits (clock, big score) and 4x7 digits (narrow score).');
lines.push('const uint8_t FONT_CLOCK[10][7] = {');
for (let d = 0; d < 10; d++) lines.push(`  {${CLOCK[String(d)].join(', ')}},`);
lines.push('};', 'const uint8_t FONT_NARROW[10][7] = {');
for (let d = 0; d < 10; d++) lines.push(`  {${NARROW[String(d)].join(', ')}},`);
lines.push('};', '');
const colorNames = Object.keys(COLORS);
lines.push('// Layout colours (0xRRGGBB).');
for (const [k, v] of Object.entries(COLORS)) lines.push(`constexpr uint32_t COLOR_${k.toUpperCase()} = 0x${rgb(v).toString(16).padStart(6, '0')};`);
lines.push('', '// 12x12 icons: one byte per pixel = index into ICON_PALETTE (0 = off).');
const keys = Object.keys(ICON_COLORS);
lines.push(`const uint32_t ICON_PALETTE[${keys.length + 1}] = {0, ${keys.map(k => '0x' + rgb(ICON_COLORS[k]).toString(16).padStart(6, '0')).join(', ')}};`);
lines.push(`constexpr int ICON_COUNT = ${Object.keys(ICONS).length};`);
lines.push(`const char *const ICON_NAMES[ICON_COUNT] = {${Object.keys(ICONS).map(n => `"${n}"`).join(', ')}};`);
lines.push('const uint8_t ICON_PIXELS[ICON_COUNT][12][12] = {');
for (const [name, rows] of Object.entries(ICONS)) {
  lines.push(`  {  // ${name}`);
  for (const row of rows) lines.push(`    {${[...row].map(ch => ch === '.' ? 0 : keys.indexOf(ch) + 1).join(', ')}},`);
  lines.push('  },');
}
lines.push('};', '');
const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'include', 'tables.h');
writeFileSync(out, lines.join('\n'));
console.log(`${out}: ${lines.length} lines`);
